@check("list：每 n 个一段，末尾凑不满的丢掉")
def t02a():
    got = chunk(list(range(7)), 3)
    true(got == [[0, 1, 2], [3, 4, 5]], f"chunk(list(range(7)), 3) 应为 [[0, 1, 2], [3, 4, 5]]，你的: {got!r}")
    got = chunk(list(range(6)), 3)
    true(got == [[0, 1, 2], [3, 4, 5]], f"chunk(list(range(6)), 3) 应为 [[0, 1, 2], [3, 4, 5]]，你的: {got!r}")
    got = chunk([], 3)
    true(got == [], f"chunk([], 3) 应为 []，你的: {got!r}")

@check("字符串也能切")
def t02b():
    got = chunk("abcdefg", 2)
    true(got == ["ab", "cd", "ef"], f"对字符串也要能用（切片是通用的）：chunk('abcdefg', 2) 应为 ['ab', 'cd', 'ef']，你的: {got!r}")

