d1-05.tests:
@check("新建时 n = 0，value = 0.0")
def t05a():
    m = RunningMean()
    true(not callable(m.value), "value 是个普通方法 —— 在它上面加一行 @property，读的时候就不用写括号")
    true(m.value == 0.0 and m.n == 0, f"新建时应该 n == 0、value == 0.0，你的: n={m.n!r}, value={m.value!r}")

@check("m(1.0); m(3.0) 之后 value = 2.0，n = 2")
def t05b():
    m = RunningMean()
    m(1.0)
    m(3.0)
    true(close(m.value, 2.0), f"均值应为 2.0，你的: {m.value}")
    true(m.n == 2, f"n 应为 2，你的: {m.n}")

@check("reset() 回到新建时的状态")
def t05c():
    m = RunningMean()
    m(1.0)
    m(3.0)
    m.reset()
    true(m.value == 0.0 and m.n == 0, f"reset() 之后应该 n == 0、value == 0.0，你的: n={m.n!r}, value={m.value!r}")

