    per_dim = 0.5 * (mu ** 2 + logvar.exp() - 1 - logvar)   # (B, D)
    return int((per_dim.mean(0) < thresh).sum())


def vae_step_buggy(x, x_hat, mu, logvar, beta=1.0):
    std = torch.exp(0.5 * logvar)                                              # fix 1
    z = mu + std * torch.randn_like(std)
