"""Day 12 reference implementations (TTS: text -> mel -> waveform).

Loaded as hidden setup by the day-12 items; each item removes the names the learner writes (its `targets:`),
so the other functions here stay available (e.g. d12-07 calls duration_from_log, d12-11 calls
make_decoder_inputs / masked_mel_loss / duration_loss).
"""
import math

import torch
import torch.nn as nn
import torch.nn.functional as F

TTS_SHAPES = {
    "文本 token id": (4, 20),
    "文本编码器输出 (C=192)": (4, 20, 192),
    "duration 预测 (log 域)": (4, 20),
    "length regulator 之后": (4, 160, 192),
    "解码器输出的 mel": (4, 160, 80),
    "vocoder 输出的波形": (4, 160 * 256),
}


def length_regulator(x, durations, max_len=None):
    outs = [x[b].repeat_interleave(durations[b], dim=0) for b in range(x.size(0))]
    Tm = max_len or max(o.size(0) for o in outs)
    out = x.new_zeros(x.size(0), Tm, x.size(2))
    for b, o in enumerate(outs):
        n = min(o.size(0), Tm)
        out[b, :n] = o[:n]
    return out


def duration_to_boundaries(durations):
    ends = durations.cumsum(0)
    starts = ends - durations
    return torch.stack([starts, ends], dim=-1)


