def curve_verdict(losses):
    if not all(math.isfinite(v) for v in losses):
        return "nan"
    if losses[-1] > 2 * losses[0]:
        return "exploding"
    if abs(losses[-1] - losses[0]) < 0.01 * losses[0]:
        return "flat"
    return "ok"


def my_cross_entropy(logits, y):
    logp = F.log_softmax(logits, dim=-1)
