def _counting_tokens(B=4, T=9, V=11):
    start = torch.randint(0, V, (B, 1))
    return (start + torch.arange(T)) % V         # 每行都是一路加 1：下一个 token 永远是「当前 + 1」

@check("会猜下一个 token 的模型，loss 接近 0")
def _():
    loss = lm_loss(NextModel(11), _counting_tokens())
    true(loss.item() < 0.01,
         f"loss = {loss.item():.3f}。NextModel 每次都猜对下一个 token，loss 应该接近 0。"
         "你是不是拿位置 t 的输出去对位置 t 的 token 了？")

@check("只会复读当前 token 的模型，loss 不能接近 0")
def _():
    loss = lm_loss(CopyModel(11), _counting_tokens())
    true(loss.item() > 1.0,
         f"loss = {loss.item():.4f}。一个只会复读的模型拿到了几乎完美的 loss，好得不真实：标签没有错位，模型在「抄答案」。")

