def _net():
    return nn.Sequential(nn.Embedding(10, 8), nn.LayerNorm(8), nn.Linear(8, 8), nn.LayerNorm(8), nn.Linear(8, 10))

@check("1 维参数不 decay，其余都 decay")
def _():
    net = _net()
    groups = param_groups(net, 0.1)
    names = {id(p): n for n, p in net.named_parameters()}
    decay = [p for g in groups if g["weight_decay"] > 0 for p in g["params"]]
    no_decay = [p for g in groups if g["weight_decay"] == 0 for p in g["params"]]
    wrong = [names[id(p)] for p in decay if p.ndim < 2]
    true(not wrong, f"这些 1 维参数被 decay 了：{wrong}。LayerNorm 的 weight 名字里没有 bias，按名字过滤会漏掉它。")
    true(sorted(names[id(p)] for p in decay) == sorted(n for n, p in net.named_parameters() if p.ndim >= 2),
         "2 维及以上的参数（Embedding、Linear 的 weight）都要在 decay 组里，而且每个只出现一次")
    true(sorted(names[id(p)] for p in no_decay) == sorted(n for n, p in net.named_parameters() if p.ndim < 2),
         "1 维参数要在 weight_decay=0 的组里，而且每个只出现一次")

@check("训练时 LayerNorm 的 weight 不会被悄悄压小")
def _():
    net = _net()
    opt = torch.optim.AdamW(param_groups(net, 0.1), lr=0.1)
    for _ in range(10):
        for p in net.parameters():
            p.grad = torch.zeros_like(p)     # 梯度是 0：参数只可能被 weight decay 改变
        opt.step()
    ln = net[1].weight
    true(torch.all(ln == 1.0),
         f"梯度一直是 0，LayerNorm 的 weight 却从 1.0 缩到了 {ln.mean().item():.3f}，这全是 weight decay 干的。")

