    def forward(self, x):  # (B, T, d)
        q, k, v = self.qkv(x).chunk(3, dim=-1)
        T = x.shape[1]
        s = q @ k.transpose(-2, -1) / math.sqrt(q.shape[-1])  # (B, T, T)
        allowed = torch.ones(T, T, dtype=torch.bool)
        if self.mask == "causal":
            allowed = allowed.tril()
        elif self.mask == "peek1":
