def _blocks():
    seed(0)
    return nn.ModuleList([nn.Sequential(nn.Linear(16, 64), nn.GELU(), nn.Dropout(0.1), nn.Linear(64, 16))
                          for _ in range(4)])

def _plain(blocks, x):
    for b in blocks:
        x = b(x)
    return x

def _grads(f, blocks, x):
    blocks.zero_grad()
    seed(1)                          # 同一个随机种子 -> 同样的 dropout mask
    f(blocks, x).pow(2).mean().backward()
    return [None if p.grad is None else p.grad.clone() for p in blocks.parameters()]

@check("输出和普通前向一样")
def _():
    blocks = _blocks()
    x = torch.randn(8, 16)
    seed(1)
    want = _plain(blocks, x)
    seed(1)
    got = forward_checkpointed(blocks, x)
    eq(got, want, tol=1e-6, msg="结果变了。checkpoint 不改变数学：每个 block 都要按顺序过一遍")

@check("x 不需要梯度时，参数梯度也完全一样")
def _():
    blocks = _blocks()
    x = torch.randn(8, 16)          # 数据本身不需要梯度
    want = _grads(_plain, blocks, x)
    try:
        got = _grads(forward_checkpointed, blocks, x)
    except RuntimeError as e:
        raise AssertionError(f"backward 报错：{str(e)[:70]}。输入都不需要梯度时，use_reentrant=True（不写时也是它）"
                             "会让这一段没有梯度 —— 写 use_reentrant=False")
    for i, (g, w) in enumerate(zip(got, want)):
        true(g is not None, f"第 {i} 个参数没有梯度 —— 用 use_reentrant=False")
        eq(g, w, tol=1e-6, msg=f"第 {i} 个参数的梯度和不用检查点时不一样")

@check("为反向存的字节少了一半以上")
def _():
    blocks = _blocks()
    x = torch.randn(8, 16)
    _, plain_n = saved_bytes(_plain, blocks, x, skip=blocks.parameters())
    _, ck_n = saved_bytes(forward_checkpointed, blocks, x, skip=blocks.parameters())
    true(ck_n < plain_n / 2, f"不用检查点时存了 {plain_n} 字节，你的存了 {ck_n} 字节 —— 每个 block 都要包在 checkpoint 里")

