import os, tempfile

def _v1_file(folder, drop=None):
    """造一个 v1 的 checkpoint：权重来自一个 Net，但最后一层叫 classifier。返回 (path, 原模型)。"""
    torch.manual_seed(7)
    net = Net().eval()
    sd = {("classifier." + k.removeprefix("head.")) if k.startswith("head.") else k: v
          for k, v in net.state_dict().items()}
    if drop:
        del sd[drop]
    path = os.path.join(folder, "v1.pt")
    torch.save(sd, path)
    return path, net

