def _clip_ref(x, max_norm):
    """原来的逐行写法（只在 PyTorch 里用来对答案）。"""
    out = x.clone()
    for i in range(len(x)):
        n = x[i].norm()
        if n > max_norm:
            out[i] = x[i] * (max_norm / n)
    return out

