ROWS = [[5.1, 3.5, 1.4, 0.2], [6.7, 3.0, 5.2, 2.3]]

@check("服务启动时就加载好模型")
def _():
    loader = CountingLoader()
    create_app(loader)
    true(loader.calls == 1, f"create_app 返回时，模型加载了 {loader.calls} 次，应为 1 次。启动时就加载好，不要让第一个用户等。")

@check("处理 5 个请求后，还是只加载了 1 次")
def _():
    loader = CountingLoader()
    client = TestClient(create_app(loader))
    for _ in range(5):
        r = client.post("/predict", json={"rows": ROWS})
        true(r.status_code == 200, f"/predict 回了 {r.status_code}")
    true(loader.calls == 1, f"处理 5 个请求后，模型一共加载了 {loader.calls} 次。每次加载都要读权重文件，真实模型要几秒到几分钟。")

@check("预测结果没变")
def _():
    client = TestClient(create_app(CountingLoader()))
    body = client.post("/predict", json={"rows": ROWS}).json()
    want = reference_probs(ROWS)
    eq(torch.tensor(body["probs"]), want, tol=1e-5, msg="概率不对：加载后记得调用 model.eval()（模型里有 Dropout）。")
    true(body["labels"] == [LABELS[i] for i in want.argmax(-1).tolist()], f"labels 不对：{body['labels']}")
    true(client.get("/health").json() == {"status": "ok"}, "/health 应该回 {'status': 'ok'}")

