                         "inference": torch.is_inference_mode_enabled(), "grad": torch.is_grad_enabled()})
        ms = self.run_ms(b)
        if b not in self.seen:
            ms += self.compile_ms
            self.seen.add(b)
        self.clock.advance(ms)
