ROWS = [[5.1, 3.5, 1.4, 0.2]]
SECRET = "CUDA out of memory (weights: /srv/models/iris-v3/model.pt)"

def _predict(rows):
    if rows[0][0] == 999:
        raise RuntimeError(SECRET)
    return reference_probs(rows).tolist()

def _client(ready):
    state = ServiceState(_predict, ready=ready)
    return state, TestClient(create_status_app(state), raise_server_exceptions=False)

@check("准备好了：/health 和 /predict 都回 200")
def _():
    state, client = _client(ready=True)
    r = client.get("/health")
    true(r.status_code == 200 and r.json() == {"status": "ok"}, f"/health 回了 {r.status_code} {r.text}")
    r = client.post("/predict", json={"rows": ROWS})
    true(r.status_code == 200, f"/predict 回了 {r.status_code}")
    eq(torch.tensor(r.json()["probs"]), reference_probs(ROWS), tol=1e-5, msg="probs 不对")

@check("没准备好：/health 回 503")
def _():
    state, client = _client(ready=False)
    r = client.get("/health")
    true(r.status_code == 503, f"模型还在加载，/health 却回了 {r.status_code}。负载均衡器只看状态码：回 200，它就把流量发过来。")
    state.ready = True
    r = client.get("/health")
    true(r.status_code == 200, f"state.ready 变成 True 以后，/health 应该回 200，你的是 {r.status_code}")

@check("没准备好：/predict 回 503，带 Retry-After")
def _():
    state, client = _client(ready=False)
    r = client.post("/predict", json={"rows": ROWS})
    true(r.status_code == 503, f"模型还没准备好，/predict 回了 {r.status_code}，应为 503")
    ra = r.headers.get("retry-after")
    true(ra is not None and ra.strip().isdigit() and int(ra) > 0, f"503 应该带 Retry-After 响应头（正整数，单位秒），你的是 {ra!r}")

@check("模型出错：回 500，不泄露细节，之后照常工作")
def _():
    state, client = _client(ready=True)
    r = client.post("/predict", json={"rows": [[999, 1.0, 1.0, 1.0]]})
    true(r.status_code == 500, f"模型抛了异常，却回了 {r.status_code}，应为 500")
    true("/srv/models" not in r.text and "out of memory" not in r.text, f"异常原文发给了客户端：{r.text}。细节写进服务器日志，给客户端只回一句 internal error。")
    r = client.post("/predict", json={"rows": ROWS})
    true(r.status_code == 200, f"出过一次错之后，正常的请求回了 {r.status_code}")

