    return app


# ---------------------------------------------------------------- warm-up / 预热
class FakeClock:
    """假时钟，单位毫秒。它不会自己走：只有 advance(ms) 或直接改 .now 才会变。测试里用它代替真实时间，不用 sleep。
    A fake clock in milliseconds. It never moves by itself: only advance(ms) or setting .now changes it."""

    def __init__(self, now=0.0):
        self.now = float(now)

    def __call__(self):
        return self.now

    def advance(self, ms):
        self.now += ms


