    ids, out = prompt_ids, []
    for _ in range(n):
        logits, _ = model(ids)
        tok = logits[0, -1].argmax().item()
        out.append(tok)
        ids = torch.cat([ids, torch.tensor([[tok]])], dim=1)
    return out


def cache_bytes(cache):
